head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > customModelFormatter]<br/>바인딩된 DataList 에 Column 값이 반영되기 전에 형식을 변환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text', 'textImage' 인 경우에 동작합니다.",
        "반드시 customModelUnformatter 속성을 함께 설정해야 합니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 파라미터로 편집된 Column 값이 전달됩니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 반환값이 바인딩된 DataList 에 적용됩니다.",
        "하위 버전 호환을 위해 유지되는 속성이며 향후 제거(Deprecated)될 예정입니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_customModelFormatter.setValue("scwin.fmt_toWon");
    con_customModelUnformatter.setValue("scwin.unfmt_toThousand");
    con_inputType.setValue("text");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// customModelFormatter : 편집된 Column 값(천원 단위)을 DataList 저장값(원 단위)으로 변환
//  - validation 3 : 전달된 파라미터 전체를 개수와 함께 출력
scwin.fmt_toWon = function (value) {
    let args = [];
    for (let i = 0; i < arguments.length; i++) {
        args.push(String(arguments[i]));
    }
    wf_body_bottom.getObj("scwin").setReturnValue("customModelFormatter 파라미터 (" + arguments.length + "개) : " + args.join(", "));
    if (value === "" || value === null || typeof value === "undefined" || isNaN(Number(value))) {
        return value;
    }
    return String(Number(value) * 1000);
}



// customModelUnformatter : DataList 저장값(원 단위)을 Column 값(천원 단위)으로 변환
scwin.unfmt_toThousand = function (value) {
    if (value === "" || value === null || typeof value === "undefined" || isNaN(Number(value))) {
        return value;
    }
    return String(Number(value) / 1000);
}



// 검증 대상 Column(Body Column 인덱스 2) 마크업
scwin.getTargetColumn = function (cInputType, cFormatter, cUnformatter) {
    let attr = '';
    if (cFormatter !== '') {
        attr += ' customModelFormatter="' + cFormatter + '"';
    }
    if (cUnformatter !== '') {
        attr += ' customModelUnformatter="' + cUnformatter + '"';
    }
    if (cInputType === "textImage") {
        attr += ' imageSrc="/cm/images/contents/btn_folder.png"';
    }
    return '<w2:column width="200" style="" inputType="' + cInputType + '" id="amt"' + attr + '></w2:column>';
}



// comp 생성
//  - name : 상품명 / amt : 금액 (DataList 는 원 단위, Column 은 천원 단위) - 검증 대상 Column (Body Column 인덱스 2)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 금액 Column(Body Column 인덱스 2) 은 천원 단위로 표시/편집, 바인딩 DataList 는 원 단위로 저장 (Formatter : x1000, Unformatter : /1000)\n[절차] 조건 선택 -> Target 재생성 -> 금액 Cell 더블클릭 -> 값 입력 -> Enter (textarea 는 다른 Cell 클릭)\n[확인] 결과창의 함수 파라미터, 편집 후 DataList 값과 화면 표시값 비교"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cFormatter = con_customModelFormatter.getValue();
    let cUnformatter = con_customModelUnformatter.getValue();
    let cInputType = con_inputType.getValue();

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amt" name="amt" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "노트북", "qty" : "3", "amt" : "1250000" },
        { "name" : "모니터", "qty" : "12", "amt" : "320000" },
        { "name" : "키보드", "qty" : "40", "amt" : "89000" },
        { "name" : "마우스", "qty" : "8", "amt" : "45000" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let eList = $c.gcm.createEList(["onafteredit"], "target1");
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:200px;" ' + eList + '>';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="수량"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column3" value="금액(천원, ' + cInputType + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += scwin.getTargetColumn(cInputType, cFormatter, cUnformatter);
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    setTimeout(function () {
        // validation 2 : 초기 DataList 값과 화면 표시값
        scwin.printDataList();
    }, 100);
}



// 검증 Column(인덱스 2) 의 화면 표시값
scwin.getDisplayStr = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_2']");
    return td ? td.textContent.trim() : "";
}



// 바인딩 DataList 값과 화면 표시값 (전체 Row)
scwin.printDataList = function () {
    let arrData = [];
    let arrDisp = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arrData.push(i + "행='" + dlt_bind.getCellData(i, "amt") + "'");
        arrDisp.push(i + "행='" + scwin.getDisplayStr(i) + "'");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("DataList amt : " + arrData.join(" / ") + "\n화면 표시값 : " + arrDisp.join(" / "));
}



// validation 1, 2, 4 : 편집 완료 후 해당 Row 의 DataList 값과 화면 표시값
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    if (columnIndex !== 2) {
        return;
    }
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("편집 후 " + rowIndex + "행 -> DataList amt='" + dlt_bind.getCellData(rowIndex, "amt") + "' / 화면 표시값='" + scwin.getDisplayStr(rowIndex) + "'");
    }, 0);
}



// validation 2 : 재표시 후(재생성 없이) DataList 값과 화면 표시값 확인
scwin.btn_checkDataList_onclick = function () {
    scwin.printDataList();
}
